    function __ESBMC_assume(bool) internal pure {}

    function run(uint addAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (addAmount)); require(addAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= addAmount);

        c.addToBalance{value: addAmount}(); if (__ESBMC_reverted()) return;
        uint recordedBeforeWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceBeforeWithdraw = address(c).balance;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint cBalanceAfterWithdraw = address(c).balance;

        assert(cBalanceBeforeWithdraw == cBalanceAfterWithdraw + recordedBeforeWithdraw);
    }

    receive() external payable {}
